<template><Layout><div class="breadcrumb"><Link :href="route('resources')">Resources</Link><span>›</span>Main categories</div><div class="page-header list-header"><div><div class="eyebrow">CATALOGUE STRUCTURE</div><h1>Main categories</h1><p>{{ items.length }} categories used across your marketplace.</p></div><Link :href="route('main-categories.create')" class="primary-button">＋ New category</Link></div><section class="listing-panel"><div class="listing-toolbar"><div class="list-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input v-model="query" placeholder="Search categories…"/></div><span>{{ filtered.length }} results</span></div><div v-if="filtered.length" class="category-table"><div class="category-row category-head"><span>Category</span><span>Created</span><span>Subcategories</span><span></span></div><Link v-for="item in filtered" :key="item.id" :href="route('main-categories.edit',{id:item.id})" class="category-row"><div class="category-identity"><span class="category-image"><img :src="item.icon" alt=""/></span><div><strong>{{ item.name }}</strong><small>ID #{{ item.id }}</small></div></div><span>{{ formatDate(item.created_at) }}</span><span>{{ item.sub_categories_count || 0 }}</span><b>›</b></Link></div><div v-else class="empty-state"><div>⌕</div><strong>{{ query?'No matching categories':'No main categories yet' }}</strong><p>{{ query?'Try another search term.':'Create your first category to organise the marketplace.' }}</p><Link v-if="!query" :href="route('main-categories.create')" class="primary-button">Create category</Link></div></section></Layout></template>
<script setup>import {ref,computed,onMounted} from 'vue';import {usePage} from '@inertiajs/vue3';import {useToast} from 'vue-toastification';import {route} from 'ziggy-js';import Layout from '../../Layouts/Layout.vue';const props=defineProps({main_categories:Object});const items=computed(()=>props.main_categories?.data||[]),query=ref('');const filtered=computed(()=>items.value.filter(i=>i.name.toLowerCase().includes(query.value.toLowerCase())));const formatDate=d=>d?new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(d)):'—';const page=usePage(),toast=useToast();onMounted(()=>{if(page.props.flash?.success)toast.success(page.props.flash.success)});</script>
